	/**
	 * Whether a profile network is Pro-only in the free build (i.e. not part
	 * of the legacy free plugin's original network set). Always false once
	 * licensed.
	 */
	public static function is_pro_network( $key ) {
		if ( Fuse_Pro::is_pro() ) {
			return false;
		}
		$all = self::profile_networks();
		return ! empty( $all[ $key ]['pro'] );
	}

	/**
	 * Networks that were supported by the old plugin but are now defunct.
	 * Never shown in the admin "add a network" list, but the migrator still
	 * recognizes these keys so old saved URLs aren't silently dropped.
	 *
	 * @return array<string, array{label:string,color:string,url_type:string}>
	 */
	public static function legacy_defunct_networks() {
		return array(
			'stumbleupon' => array( 'label' => 'StumbleUpon (defunct)', 'color' => '#EB4924', 'url_type' => 'url' ),
			'vine'        => array( 'label' => 'Vine (defunct)', 'color' => '#00BF8F', 'url_type' => 'url' ),
			'google-plus' => array( 'label' => 'Google+ (defunct)', 'color' => '#DD4B39', 'url_type' => 'url' ),
		);
	}

	/**
	 * All profile networks, including legacy/defunct ones (used when
	 * resolving a network key to a label/color/icon regardless of source).
	 */
	public static function all_profile_networks() {
		return array_merge( self::profile_networks(), self::legacy_defunct_networks() );
	}

