	/**
	 * Render an inline <svg> for a given icon key.
	 */
	public static function get_icon_svg( $key, $size = 20, $extra_class = '' ) {
		$icons = self::icons();

		if ( empty( $icons[ $key ] ) ) {
			return '';
		}

		$icon = $icons[ $key ];
		$size = absint( $size );

		return sprintf(
			'<svg class="fsi-icon-svg %5$s" viewBox="%1$s" width="%2$d" height="%2$d" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false"><path d="%3$s" fill="currentColor"/></svg>',
			esc_attr( $icon['viewbox'] ),
			$size,
			esc_attr( $icon['path'] ),
			'',
			esc_attr( $extra_class )
		);
	}

	/**
	 * Resolve label/color/icon for any profile network key (active or legacy).
	 */
	public static function get_profile_network( $key ) {
		$all = self::all_profile_networks();
		return isset( $all[ $key ] ) ? $all[ $key ] : null;
	}

	public static function get_share_network( $key ) {
		$all = self::share_networks();
		return isset( $all[ $key ] ) ? $all[ $key ] : null;
	}
